const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometries for the islands
  const robinsonCrusoe = ee.Geometry.Point([-78.8417, -33.6411]).buffer(2000);
  const santaClara = ee.Geometry.Point([-78.9500, -33.7000]).buffer(1500);

  // Date range for November 2018
  const startDate = '2018-11-01';
  const endDate = '2018-11-30';

  // Get Sentinel-2 collection
  let s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

  // Check collection size
  const colSize = s2Col.size().getInfo();
  console.log(`Total images in period: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Function to calculate NDVI and mask clouds
  function processImage(img) {
    // Cloud masking using QA60 band
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    // Calculate NDVI
    const ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI');

    return img.addBands(ndvi).updateMask(mask);
  }

  // Process collection
  s2Col = s2Col.map(processImage).select('NDVI');

  // Create composite
  const composite = s2Col.median();

  // Calculate mean NDVI for each island
  const robinsonStats = composite.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: robinsonCrusoe,
    scale: 100,
    maxPixels: 1e9
  });

  const santaClaraStats = composite.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: santaClara,
    scale: 100,
    maxPixels: 1e9
  });

  const robinsonData = robinsonStats.getInfo();
  const santaClaraData = santaClaraStats.getInfo();

  console.log(`Robinson: NDVI=${robinsonData.NDVI_mean?.toFixed(3)}, Pixels=${robinsonData.NDVI_count}`);
  console.log(`Santa Clara: NDVI=${santaClaraData.NDVI_mean?.toFixed(3)}, Pixels=${santaClaraData.NDVI_count}`);

  // Check for no valid pixels
  if (!robinsonData.NDVI_count || !santaClaraData.NDVI_count || 
      robinsonData.NDVI_count === 0 || santaClaraData.NDVI_count === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (robinsonData.NDVI_mean === null || santaClaraData.NDVI_mean === null ||
      isNaN(robinsonData.NDVI_mean) || isNaN(santaClaraData.NDVI_mean) ||
      Math.abs(robinsonData.NDVI_mean) > 1 || Math.abs(santaClaraData.NDVI_mean) > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare NDVI values
  if (robinsonData.NDVI_mean > santaClaraData.NDVI_mean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
